// The HTTP Request node's array-splitting behaviour for a top-level JSON array
// response has varied across n8n versions, so don't assume it always turns one
// PostgREST array into one item per row. Normalize defensively here: flatten any
// array-shaped item.json into individual rows, drop anything without an id or post_id
// (both are required for everything downstream).
const inputItems = $input.all();
const rows = [];
for (const item of inputItems) {
  const value = item.json;
  if (Array.isArray(value)) {
    rows.push(...value);
  } else if (value) {
    rows.push(value);
  }
}
return rows.filter(row => row && row.id && row.post_id).map(row => ({ json: row }));

// Fetch Instagram Credential's HTTP output replaced $json with the credential
// lookup's response body, which drops the post row's own fields (post_id,
// branch_slug, etc). Pull the post row back from 'Normalize Posts To Check' at
// the same item index and merge in the resolved access token.
const post = $('Normalize Posts To Check').item.json;
const cred = $input.item.json || {};

if (!cred.success) {
  throw new Error('Credential lookup failed for branch ' + post.branch_id + ': ' + (cred.error || 'unknown error'));
}
const accessToken = (cred.access_token || '').trim();
if (!accessToken) {
  throw new Error('access_token came back empty for branch ' + post.branch_id);
}

return { json: { ...post, access_token: accessToken } };

// Instagram's Graph API metric names don't line up 1:1 with our column names
// (it's "saved", not "saves"), and "shares" in particular may be entirely
// absent depending on API version and whether the media is an image, carousel,
// or Reel. Look each metric up by name in data[] and default to 0 rather than
// fail the whole row over one missing field -- a mostly-zero row because
// Instagram simply didn't return that metric is expected, not an error.
const response = $input.item.json || {};
const source = $('Merge Credential With Post').item.json || {};
const metricsData = Array.isArray(response.data) ? response.data : [];

function metricValue(name) {
  const entry = metricsData.find(m => m && m.name === name);
  const raw = entry && Array.isArray(entry.values) && entry.values.length ? entry.values[0].value : undefined;
  const num = Number(raw);
  return Number.isFinite(num) ? num : 0;
}

return { json: {
  scheduled_post_id: source.id || null,
  ig_media_id: source.post_id || null,
  branch_slug: source.branch_slug || null,
  impressions: metricValue('views') || metricValue('impressions'),
  reach: metricValue('reach'),
  likes: metricValue('likes'),
  comments: metricValue('comments'),
  saves: metricValue('saved'),
  shares: metricValue('shares'),
  raw: response,
  fetched_at: new Date().toISOString(),
} };
